import { Link, useLocation } from 'react-router-dom';

const navItems = [
    { path: '/dashboard', icon: 'dashboard', label: 'Overview' },
    { path: '/devices', icon: 'devices', label: 'Devices' },
    { path: '/alerts', icon: 'notifications', label: 'Alerts' },
    { path: '/profile', icon: 'person', label: 'Profile' },
    { path: '/settings', icon: 'settings', label: 'Settings' }
];

function Sidebar({ isOpen, onClose }) {
    const location = useLocation();

    return (
        <>
            {/* Mobile Overlay */}
            {isOpen && (
                <div 
                    className="fixed inset-0 bg-black/50 z-40 md:hidden backdrop-blur-sm"
                    onClick={onClose}
                />
            )}

            <aside className={`
                fixed left-0 top-0 h-full w-72 bg-surface-container-lowest z-50 flex flex-col border-r border-glass-stroke backdrop-blur-xl transition-transform duration-300
                ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
            `}>

                {/* Logo */}
                <div className="p-6 flex items-center justify-between mb-2">
                    <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-sky-blue to-deep-sky-blue flex items-center justify-center text-lg font-bold text-white shadow-lg">
                            ⚡
                        </div>
                        <span className="text-title-md font-inter font-medium text-on-surface">
                            WattWise
                        </span>
                    </div>
                    <button className="md:hidden text-on-surface-variant hover:text-sky-blue" onClick={onClose}>
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>

                {/* Navigation */}
                <nav className="flex-1 px-6 mt-2 space-y-1">
                    {navItems.map((item) => {
                        const isActive = location.pathname === item.path;
                        return (
                            <Link
                                key={item.path}
                                to={item.path}
                                onClick={onClose}
                                className={`
                                    flex items-center px-4 py-3 rounded-lg transition-all duration-200 group
                                    ${isActive
                                        ? 'bg-sky-blue/10 text-sky-blue border border-sky-blue/20'
                                        : 'text-on-surface-variant hover:bg-surface-container-highest hover:text-on-surface border border-transparent'
                                    }
                                `}
                            >
                                <span className={`material-symbols-outlined mr-3 ${
                                    isActive ? 'text-sky-blue' : 'group-hover:text-sky-blue'
                                }`}>
                                    {item.icon}
                                </span>
                                <span className="font-inter text-body-md">
                                    {item.label}
                                </span>
                            </Link>
                        );
                    })}
                </nav>

                {/* System Status */}
                <div className="px-6 py-6 border-t border-glass-stroke">
                    <div className="p-4 rounded-xl bg-surface-container-high/50 backdrop-blur-md flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-sky-blue animate-pulse" />
                        <span className="text-label-caps font-inter text-on-surface-variant uppercase">
                            System: Optimal
                        </span>
                    </div>
                </div>

            </aside>
        </>
    );
}

export default Sidebar;
